  let nodeFamilies = [];
  if (contract?.node_families !== undefined) {
    if (!Array.isArray(contract.node_families)) {
      recordBlocker('invalid_node_families');
      nodeFamilies = [];
    } else {
      nodeFamilies = contract.node_families;
    }
  }
  return nodeFamilies
    .filter((node) => node && typeof node === 'object')
    .map((node) => ({
      node_family: node.node_family ?? null,
      stable_id_rule: node.stable_id_rule ?? null,
      required_source: node.required_source ?? null,
      population_status: populatedFamilies.has(node.node_family)
        ? 'populated_current_issue'
        : 'pending_later_issue',
    }))
    .sort((left, right) => compareByteOrder(left.node_family, right.node_family));
